import * as React from "react";
import {Icon,type IconProps} from "@/components/ui/icon";

export type ZoomInIconProps=Omit<IconProps,"name">;
/** Lucide "zoom-in" through the Cojeev Icon: motion presets, sizes and feedback included. */
export function ZoomInIcon(props:ZoomInIconProps){return <Icon name="zoom-in" {...props}/>;}
